/**
 * An Olm message as sent over the wire: type 0 = pre-key (first message of a session), 1 = normal. [body] is base64.
 */
public struct Encrypted {
    public var msgType: UInt8
    public var body: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(msgType: UInt8, body: String) {
        self.msgType = msgType
        self.body = body
    }
}



extension Encrypted: Equatable, Hashable {
    public static func ==(lhs: Encrypted, rhs: Encrypted) -> Bool {
        if lhs.msgType != rhs.msgType {
            return false
        }
        if lhs.body != rhs.body {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(msgType)
        hasher.combine(body)
    }
}


